using System.Collections.Generic;
using UnityEngine;

// THE GUN TABLE.
// Every gun (except the 4 originals, which have their own code) is ONE entry below. Change a number and the gun changes.
// To add a new gun:
//   1. add its name to ItemId (Items.cs, at the END of the list)
//   2. add its recipe to Items.All (Items.cs, "More guns")
//   3. add a GunDef here
// That's it - firing, damage, the model in your hands and the hotbar all come from this.
//
//   mode       Hitscan = instant bullet/laser.  Beam = short spray you hold (flamethrower).  Projectile = a flying shot.
//   look       which kind of model is built in your scientist's hands (Pistol, Rifle, Shotgun, ...)
//   damage     per bullet / per pellet / per beam tick
//   cooldown   seconds between shots (lower = faster)
//   heat       heat added per shot; 100 = overheated
//   auto       true = hold to keep firing, false = click for every shot
//   pellets    bullets per shot (shotguns)      spread  how wide they go (degrees)
//   burst      shots fired by one click (burst guns)
//   pierce     goes through targets              chain   jumps to this many more targets (lightning)
//   speed / gravity / blast / size / puddle      for Projectile guns (blast > 0 = it explodes)
//   structure  extra damage against labs (1 = normal)
//   element    Fire / Ice / Poison / Slime / Shock built in (an enchant replaces it)

public enum GunMode { Hitscan, Beam, Projectile, Melee, Wave, Gadget }
//   Melee  = swing at everything in front of you (reach / arc / lunge)
//   Wave   = a shockwave, gust or sound blast from where you stand (wave / arc)
//   Gadget = doesn't shoot at all - it only does its special thing (wall, decoy, heal zone, orbs, turret...)
public enum GunLook { Pistol, Revolver, SMG, Rifle, Musket, Shotgun, Sniper, Railgun, Launcher, Sprayer, Blaster, Coil,
    Blade, Hammer, Spear, Staff, Wand, Orb, Shield, Whip, Bow, Fan, Gauntlet, Jar, Disc, Bell }

public class GunDef
{
    public ItemId id;
    public GunMode mode;
    public GunLook look;
    public float damage = 10f, cooldown = 0.2f, heat = 8f, range = 90f;
    public bool auto = true;
    public int pellets = 1;
    public float spread;
    public int burst = 1;
    public float burstGap = 0.08f;
    public bool pierce;
    public int chain;
    public float force = 0.8f;
    public float speed = 60f, gravity, blast, size = 0.14f, life = 3f;
    public bool puddle, star;
    public float structure = 1f;
    public Element element;
    public Color color = Color.white;           // shots and glowing bits
    public Color body = new Color(0.22f, 0.24f, 0.27f);   // the gun itself
    public Color trim = new Color(0.75f, 0.77f, 0.8f);
    public string sound = "zap";
    public float pitch = 1f, volume = 0.55f, kick = 0.4f;
    public bool lightning;                      // zig-zag tracer
    public float hitBlast, lifesteal, crit;     // usually from enchants

    // ---- special mechanics (0 / false = off) ----
    public float homing;            // projectiles steer towards enemies (turn speed, degrees a second)
    public int bounces;             // projectiles bounce off walls and the ground this many times
    public int ricochet;            // instant shots bounce off walls this many times
    public int cluster;             // explosions throw out this many mini bombs
    public float stick;             // sticks to whatever it hits and explodes after this many seconds
    public bool boomerang;          // flies out, comes back, and goes through everything both ways
    public float flak;              // bursts in the air after flying this far (into 'pellets' bits, or a blast)
    public bool wallPierce;         // instant shots go through walls
    public float selfKnock;         // pushes YOU backwards (rocket jumps, shotgun jumps)
    public bool grapple;            // pulls you to wherever you hit
    public bool teleport;           // teleports you to where the shot lands
    public float strike;            // marks the spot you aim at; something big lands there after this many seconds
    public float field;             // leaves a damaging patch this big where it lands (fire, acid, ice...)
    public float fieldTime = 5f;
    public bool blackHole;          // the field pulls people in
    public bool turret;             // throws out a mini turret that shoots enemies for 'fieldTime' seconds
    public int mag;                 // magazine size (instead of overheating). R reloads.
    public float reload = 1.5f;     // reload time
    public float charge;            // hold to charge up (seconds to full); let go to fire. Full charge = (1 + chargeBonus) x damage
    public float chargeBonus = 2f;
    public float spinUp;            // starts slow and speeds up while you hold it (seconds to full speed)

    // ---- melee, waves and gadgets (the big weapon list) ----
    public float reach = 2.8f;      // MELEE: how far the swing reaches
    public float arc = 100f;        // MELEE / WAVE: how wide (degrees; 360 = all around you)
    public float lunge;             // dashes you forward this far when you attack
    public float wave;              // WAVE: how big the shockwave / gust / sound blast is
    public float pull;              // pulls what you hit towards you (negative = shoves it away)
    public float mark;              // marks what you hit: it takes this much extra damage (0.3 = +30%) for 6 s
    public bool block;              // SHIELD: hold right-click to block 75% of damage from the front
    public bool barrier;            // puts a wall down in front of you for 'fieldTime' seconds
    public bool decoy;              // drops a decoy scientist that explodes after 'fieldTime' seconds
    public float healZone;          // drops a healing circle this big where you stand
    public int orbit;               // summons this many orbs that circle you and hit enemies
    public bool reveal;             // marks every enemy within 30 m
    public bool cycle;              // each attack switches element: fire, ice, poison, shock
    public float blink;             // teleports you this far towards where you aim
    public float buffSpeed = 1f, buffDamage = 1f;    // a 4-second boost for you every attack
    public float heal;              // heals you this much every attack

    public GunDef Clone() => (GunDef)MemberwiseClone();
}

